CREATE TABLE `Bil_Dimension_Rule` (
  `rowid` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `rule_code` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则编码',
  `rule_name` varchar(200) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则名称',
  `event_code` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件编码',
  `biz_category` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务分类',
  `account_set_id` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账套ID',
  `priority` int NOT NULL DEFAULT 100 COMMENT '优先级',
  `voucher_required` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否需要凭证',
  `auto_voucher_write` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否自动写凭证',
  `status` bit(1) NOT NULL DEFAULT b'1' COMMENT '启用状态',
  `stop_after_match` bit(1) NOT NULL DEFAULT b'1' COMMENT '命中后停止',
  `description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `lingma_sys_ent` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '租户/企业编码',
  `lingma_sys_is_delete` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否软删除',
  `createuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `createtime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updatetime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `wfid` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例id',
  `flowstate` int DEFAULT NULL COMMENT '流程状态',
  `ReportID` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报表id',
  PRIMARY KEY (`rowid`),
  UNIQUE KEY `uk_dimension_rule_code` (`rule_code`),
  KEY `idx_dimension_rule_event_code` (`event_code`),
  KEY `idx_dimension_rule_biz_category` (`biz_category`),
  KEY `idx_dimension_rule_account_set_id` (`account_set_id`),
  KEY `idx_dimension_rule_is_delete` (`lingma_sys_is_delete`),
  KEY `idx_dimension_rule_status_priority` (`status`,`priority`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='维度规则主表';

CREATE TABLE `Bil_Dimension_Rule_Condition` (
  `rowid` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `rule_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则ID',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序号',
  `field_code` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '字段编码',
  `operator` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '运算符',
  `value_source` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '取值来源 CONST/FIELD',
  `compare_value` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '比较值',
  `compare_field` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '比较字段',
  `description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `lingma_sys_ent` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '租户/企业编码',
  `lingma_sys_is_delete` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否软删除',
  `createuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `createtime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updatetime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `wfid` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例id',
  `flowstate` int DEFAULT NULL COMMENT '流程状态',
  `ReportID` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报表id',
  PRIMARY KEY (`rowid`),
  KEY `idx_dimension_rule_condition_rule_id` (`rule_id`),
  KEY `idx_dimension_rule_condition_sort_no` (`sort_no`),
  KEY `idx_dimension_rule_condition_is_delete` (`lingma_sys_is_delete`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='维度规则条件表';

CREATE TABLE `Bil_Dimension_Rule_Result` (
  `rowid` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `rule_id` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '规则ID',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序号',
  `dim_category` varchar(30) COLLATE utf8mb4_general_ci NOT NULL COMMENT '维度分类',
  `dim_code` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '维度编码',
  `value_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL COMMENT '取值方式',
  `value_expr` varchar(500) COLLATE utf8mb4_general_ci NOT NULL COMMENT '取值表达式',
  `amount_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'NONE' COMMENT '金额方式',
  `amount_expr` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '金额表达式',
  `direction_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '方向方式',
  `direction_expr` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '方向表达式',
  `currency_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '币种方式',
  `currency_expr` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '币种表达式',
  `period_type` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '期间方式',
  `period_expr` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '期间表达式',
  `required_flag` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否必填',
  `description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `lingma_sys_ent` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '租户/企业编码',
  `lingma_sys_is_delete` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否软删除',
  `createuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `createtime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updatetime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `wfid` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例id',
  `flowstate` int DEFAULT NULL COMMENT '流程状态',
  `ReportID` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报表id',
  PRIMARY KEY (`rowid`),
  KEY `idx_dimension_rule_result_rule_id` (`rule_id`),
  KEY `idx_dimension_rule_result_sort_no` (`sort_no`),
  KEY `idx_dimension_rule_result_dim_code` (`dim_code`),
  KEY `idx_dimension_rule_result_is_delete` (`lingma_sys_is_delete`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='维度规则结果表';

