CREATE TABLE `Bil_Dimension_Biz_Category` (
  `rowid` varchar(32) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `biz_category_code` varchar(50) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务分类编码',
  `biz_category_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务分类名称',
  `sort_no` int NOT NULL DEFAULT 1 COMMENT '排序号',
  `status` bit(1) NOT NULL DEFAULT b'1' COMMENT '状态',
  `description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '描述',
  `lingma_sys_ent` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '租户/企业编码',
  `lingma_sys_is_delete` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否软删除',
  `createuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `createtime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateuser` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `updatetime` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `wfid` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '流程实例id',
  `flowstate` int DEFAULT NULL COMMENT '流程状态',
  `ReportID` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '报表id',
  PRIMARY KEY (`rowid`),
  UNIQUE KEY `uk_dimension_biz_category_code` (`biz_category_code`),
  KEY `idx_dimension_biz_category_status` (`status`,`sort_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='维度业务分类字典表';

